/**
 * Flutter Remote WebRTC V3 ServeSimConsumer (CommonJS)
 *
 * Owns:
 *   1. HTTP client for serve-sim MJPEG stream (SOI/EOI boundary demarcation)
 *   2. Feeding parsed JPEGs to VideoEncoder & legacy /stream-ws subscribers
 *   3. WebSocket client bridge to serve-sim's input socket (/helper/<udid>/ws),
 *      translating browser input into serve-sim's binary frames, with offline
 *      queueing & move coalescing (see serveSimProtocol.cjs)
 */

const http = require('node:http');
const { createJpegSplitter } = require('./mjpeg.cjs');
const { toServeSimFrames, isTouchMoveFrame, inputPathFor } = require('./serveSimProtocol.cjs');

class ServeSimConsumer {
  constructor(options = {}) {
    this.targetHost = options.targetHost || '127.0.0.1';
    this.previewPort = options.previewPort || 3200;
    this.streamPath = options.streamPath || '/stream.mjpeg?raw=1';
    this.videoEncoder = options.videoEncoder || null;
    this.streamWsClients = options.streamWsClients || new Set();
    this.activeVideoTracks = options.activeVideoTracks || new Set();
    this.WebSocketClass = options.WebSocketClass || null;
    this.inputPath = inputPathFor({ inputPath: options.inputPath, streamPath: this.streamPath });

    this.localStreamReq = null;
    this.jpegFrameCount = 0;
    this.frameWarningTimer = null;
    this.reconnectTimer = null;
    this._streamStuckTimer = null;
    this._closed = false;

    // WebSocket bridge state
    this.serveSimWs = null;
    this.serveSimQueue = [];
    this.serveSimConnecting = false;
  }

  ensureLocalStream() {
    if (this.streamWsClients.size === 0 && this.activeVideoTracks.size === 0) {
      return;
    }
    if (this.localStreamReq) {
      // Guard against stuck requests: if connected but 0 frames after 4s, destroy and restart.
      if (!this._streamStuckTimer && this.jpegFrameCount === 0) {
        this._streamStuckTimer = setTimeout(() => {
          this._streamStuckTimer = null;
          if (this.jpegFrameCount === 0 && this.localStreamReq) {
            console.warn('[webrtc-peer] serve-sim stream stuck — 0 frames in 4s, restarting connection');
            const req = this.localStreamReq;
            this.localStreamReq = null;
            try { req.destroy(); } catch {}
            this.ensureLocalStream();
          }
        }, 4000);
      }
      return;
    }
    this._closed = false;

    console.log('[webrtc-peer] starting serve-sim stream consumer');
    console.log(
      `[webrtc-peer] Connecting to serve-sim stream: http://${this.targetHost}:${this.previewPort}${this.streamPath}`
    );

    this.localStreamReq = http.get(
      {
        host: this.targetHost,
        port: this.previewPort,
        path: this.streamPath,
        headers: { 'Accept-Encoding': 'identity' },
      },
      (res) => {
        console.log(
          `[webrtc-peer] serve-sim stream response: status=${res.statusCode} content-type=${res.headers['content-type'] || 'unknown'}`
        );

        if (res.statusCode !== 200) {
          console.error(
            `[webrtc-peer] serve-sim stream failed:\n` +
            `host=${this.targetHost}\n` +
            `port=${this.previewPort}\n` +
            `path=${this.streamPath}\n` +
            `status=${res.statusCode}\n` +
            `content-type=${res.headers['content-type'] || 'unknown'}`
          );
        }

        if (res.statusCode === 200) {
          if (this.frameWarningTimer) {
            clearTimeout(this.frameWarningTimer);
          }
          this.frameWarningTimer = setTimeout(() => {
            if (this.jpegFrameCount === 0) {
              console.warn(
                `[webrtc-peer] [video] WARNING: Connected to serve-sim stream: http://${this.targetHost}:${this.previewPort}${this.streamPath} but 0 JPEG frames parsed after 5s — check --codec (expected mjpeg)!`
              );
            }
          }, 5000);
        }

        const splitter = createJpegSplitter((jpeg) => {
          if (this.frameWarningTimer) {
            clearTimeout(this.frameWarningTimer);
            this.frameWarningTimer = null;
          }
          this.jpegFrameCount++;

          if (this._streamStuckTimer) {
            clearTimeout(this._streamStuckTimer);
            this._streamStuckTimer = null;
          }

          if (this.jpegFrameCount <= 3 || this.jpegFrameCount % 60 === 0) {
            console.log(`[video] JPEG frames=${this.jpegFrameCount} size=${jpeg.length}`);
          }

          // 1. Broadcast raw JPEG to WebSocket clients (legacy fallback)
          for (const client of this.streamWsClients) {
            if (client.readyState === 1 /* OPEN */) {
              try { client.send(jpeg); } catch {}
            }
          }

          // 2. Feed JPEG into real H.264 VideoEncoder
          if (this.activeVideoTracks.size > 0 && this.videoEncoder) {
            this.videoEncoder.encodeFrame(jpeg);
          }
        });

        res.on('data', (chunk) => splitter.push(chunk));

        const scheduleReconnect = () => {
          if (!this._closed && !this.reconnectTimer && (this.streamWsClients.size > 0 || this.activeVideoTracks.size > 0)) {
            this.reconnectTimer = setTimeout(() => {
              this.reconnectTimer = null;
              this.ensureLocalStream();
            }, 1000);
          }
        };

        res.on('end', () => {
          if (this.frameWarningTimer) {
            clearTimeout(this.frameWarningTimer);
            this.frameWarningTimer = null;
          }
          this.localStreamReq = null;
          scheduleReconnect();
        });

        res.on('error', (err) => {
          if (this.frameWarningTimer) {
            clearTimeout(this.frameWarningTimer);
            this.frameWarningTimer = null;
          }
          console.error('[webrtc-peer local stream error]', err.message);
          this.localStreamReq = null;
          scheduleReconnect();
        });
      }
    );

    this.localStreamReq.on('error', (err) => {
      if (this.frameWarningTimer) {
        clearTimeout(this.frameWarningTimer);
        this.frameWarningTimer = null;
      }
      console.error('[webrtc-peer local stream request error]', err.message);
      this.localStreamReq = null;
      if (!this._closed && !this.reconnectTimer && (this.streamWsClients.size > 0 || this.activeVideoTracks.size > 0)) {
        this.reconnectTimer = setTimeout(() => {
          this.reconnectTimer = null;
          this.ensureLocalStream();
        }, 1000);
      }
    });
  }

  sendToServeSim(msg) {
    // Browser messages are JSON; serve-sim only understands binary tag+JSON frames.
    const frames = toServeSimFrames(msg);
    for (const f of frames) this._sendFrame(f);
  }

  _sendFrame(buf) {
    if (this.serveSimWs && this.serveSimWs.readyState === 1 /* OPEN */) {
      try {
        this.serveSimWs.send(buf, { binary: true });
        return;
      } catch {}
    }

    if (this.serveSimQueue.length < 500) {
      if (isTouchMoveFrame(buf)) {
        const lastIdx = this.serveSimQueue.findLastIndex((item) => isTouchMoveFrame(item));
        if (lastIdx !== -1 && lastIdx === this.serveSimQueue.length - 1) {
          this.serveSimQueue[lastIdx] = buf;
          return;
        }
      }
      this.serveSimQueue.push(buf);
    }

    this.initServeSimWs();
  }

  initServeSimWs() {
    if (!this.WebSocketClass) return;
    if (this.serveSimConnecting || (this.serveSimWs && this.serveSimWs.readyState === 1 /* OPEN */)) return;
    this.serveSimConnecting = true;

    const url = `ws://${this.targetHost}:${this.previewPort}${this.inputPath}`;
    const ws = new this.WebSocketClass(url);
    this.serveSimWs = ws;

    ws.on('open', () => {
      this.serveSimConnecting = false;
      console.log(`[webrtc-peer] Connected to serve-sim input ${this.inputPath}, flushing queue of`, this.serveSimQueue.length);
      while (this.serveSimQueue.length > 0 && ws.readyState === 1) {
        const m = this.serveSimQueue.shift();
        try { ws.send(m, { binary: true }); } catch {}
      }
    });

    ws.on('error', (err) => {
      this.serveSimConnecting = false;
      // Loud on purpose: a wrong input path means taps silently do nothing.
      console.warn(`[webrtc-peer -> serve-sim input ${url}] ${err.message}`);
    });

    this.serveSimWs.on('close', () => {
      this.serveSimConnecting = false;
    });
  }

  close() {
    this._closed = true;
    if (this._streamStuckTimer) {
      clearTimeout(this._streamStuckTimer);
      this._streamStuckTimer = null;
    }
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.frameWarningTimer) {
      clearTimeout(this.frameWarningTimer);
      this.frameWarningTimer = null;
    }
    if (this.localStreamReq) {
      const req = this.localStreamReq;
      this.localStreamReq = null;
      try { req.destroy(); } catch {}
    }
    if (this.serveSimWs) {
      try { this.serveSimWs.close(); } catch {}
      this.serveSimWs = null;
    }
    this.serveSimQueue = [];
    this.serveSimConnecting = false;
  }
}

module.exports = {
  ServeSimConsumer,
};
